<script setup lang="ts">
definePageMeta({ layout: 'dashboard', middleware: 'admin' }); useSeoMeta({ title: 'Paiements et frais', robots: 'noindex' })
const toast = useToast()
const { data: fees } = await useAsyncData('adm-fees', () => api<any>('/api/admin/fees'), { server: false }); const fee = reactive({ platformFeeEnabled: false, platformPercentBp: 0, platformFixedPerTicket: 0, providerFeeEnabled: false, providerPercentBp: 0, providerFixed: 0, buyerPaysFees: false }); watch(fees, (v) => { if (v) Object.assign(fee, v) }, { immediate: true })
const platformPercent = computed({ get: () => fee.platformPercentBp / 100, set: (value: number) => { fee.platformPercentBp = Math.round(value * 100) } })
const providerPercent = computed({ get: () => fee.providerPercentBp / 100, set: (value: number) => { fee.providerPercentBp = Math.round(value * 100) } })
const { data: fin, refresh } = await useAsyncData('adm-fin', () => api<any>('/api/admin/finance'), { server: false })
async function saveFees() { try { await api('/api/admin/fees', { method: 'PUT', body: fee }); toast.ok('Frais enregistrés et tracés dans le journal d’audit') } catch (e) { toast.err(errMsg(e)) } }
const s = reactive({ organizationId: '', gross: 0, providerFees: 0, platformFees: 0, reference: '', paid: true })
async function settle() { try { await api('/api/admin/settlements', { method: 'POST', body: { ...s, reference: s.reference || undefined } }); toast.ok('Reversement enregistré'); refresh() } catch (e) { toast.err(errMsg(e)) } }
async function updateSettlement(id: string, status: 'paid' | 'cancelled') { try { await api(`/api/admin/settlements/${id}`, { method: 'PATCH', body: { status } }); toast.ok(status === 'paid' ? 'Reversement marqué comme payé' : 'Reversement annulé'); refresh() } catch (e) { toast.err(errMsg(e)) } }
</script>
<template><div class="space-y-8"><h1 class="text-[clamp(1.8rem,4vw,2.6rem)] font-black">Paiements, frais et commissions</h1>
  <form class="card grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-3" @submit.prevent="saveFees"><h2 class="text-lg font-bold sm:col-span-2 lg:col-span-3">Tarifs TYPS — désactivés par défaut, modifiables ici</h2>
    <label class="flex min-h-[44px] items-center gap-3 sm:col-span-2 lg:col-span-3"><input v-model="fee.platformFeeEnabled" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]">Activer la commission TYPS sur les ventes</label>
    <label class="block"><span class="label">Commission TYPS (%)</span><input v-model.number="platformPercent" type="number" min="0" max="50" step="0.01" class="input"><span class="hint">Pourcentage, précis au centième.</span></label><label class="block"><span class="label">Commission fixe par billet (FCFA)</span><input v-model.number="fee.platformFixedPerTicket" type="number" min="0" class="input"></label>
    <label class="flex min-h-[44px] items-center gap-3 sm:col-span-2 lg:col-span-3"><input v-model="fee.providerFeeEnabled" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]">Inclure une estimation des frais FedaPay dans le calcul des reversements</label>
    <label class="block"><span class="label">Estimation FedaPay (%)</span><input v-model.number="providerPercent" type="number" min="0" max="50" step="0.01" class="input"></label><label class="block"><span class="label">Estimation FedaPay fixe (FCFA/commande)</span><input v-model.number="fee.providerFixed" type="number" min="0" class="input"></label>
    <label class="flex min-h-[44px] items-center gap-3 sm:col-span-2 lg:col-span-3"><input v-model="fee.buyerPaysFees" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]">Ajouter les frais activés au total payé par l’acheteur (sinon déduits du net organisateur)</label>
    <button class="btn btn-primary sm:col-span-2 lg:col-span-3">Enregistrer les tarifs</button><p class="hint sm:col-span-2 lg:col-span-3">Toute modification est journalisée. Les taux FedaPay sont des estimations, pas des frais confirmés par le prestataire. L’abonnement organisateur et les reversements automatiques ne sont pas disponibles : ne les annonce pas comme actifs.</p></form>
  <div class="card overflow-x-auto"><h2 class="p-5 text-lg font-bold">Rapprochement par organisation</h2><table class="w-full min-w-[760px]"><thead><tr><th class="th">Organisation</th><th class="th">Net en ligne</th><th class="th">Déjà payé</th><th class="th">En attente</th><th class="th">Disponible</th></tr></thead><tbody class="divide-y divide-line"><tr v-for="d in fin?.due" :key="d.organization_id"><td class="td">{{ d.name }}<span class="block font-mono text-[0.65rem] text-muted">{{ d.organization_id }}</span></td><td class="td">{{ money(Number(d.online_net)) }}</td><td class="td">{{ money(Number(d.settled)) }}</td><td class="td">{{ money(Number(d.pending)) }}</td><td class="td font-semibold text-accent">{{ money(Number(d.online_net) - Number(d.settled) - Number(d.pending)) }}</td></tr></tbody></table></div>
  <form class="card grid gap-4 p-5 sm:grid-cols-2 lg:grid-cols-4" @submit.prevent="settle"><h2 class="text-lg font-bold sm:col-span-2 lg:col-span-4">Enregistrer un reversement (manuel)</h2><label class="block sm:col-span-2"><span class="label">ID de l’organisation</span><input v-model="s.organizationId" required class="input font-mono text-xs"></label><label class="block"><span class="label">Brut</span><input v-model.number="s.gross" type="number" min="0" class="input"></label><label class="block"><span class="label">Frais prestataire</span><input v-model.number="s.providerFees" type="number" min="0" class="input"></label><label class="block"><span class="label">Commission TYPS</span><input v-model.number="s.platformFees" type="number" min="0" class="input"></label><label class="block"><span class="label">Référence du virement</span><input v-model="s.reference" class="input"></label><label class="flex min-h-[44px] items-center gap-3"><input v-model="s.paid" type="checkbox" class="h-5 w-5 accent-[rgb(var(--c-a))]">Déjà payé</label><button class="btn btn-primary">Enregistrer</button></form>
  <div class="card overflow-x-auto"><h2 class="p-5 text-lg font-bold">Historique des reversements</h2><table class="w-full min-w-[760px]"><thead><tr><th class="th">Date</th><th class="th">Organisation</th><th class="th">Net</th><th class="th">Statut</th><th class="th">Référence</th><th class="th">Actions</th></tr></thead><tbody class="divide-y divide-line"><tr v-for="p in fin?.settlements" :key="p.id"><td class="td">{{ fdate(p.createdAt, { dateStyle: 'short' }) }}</td><td class="td font-mono text-xs">{{ p.organizationId.slice(0, 8) }}</td><td class="td">{{ money(p.net) }}</td><td class="td capitalize">{{ p.status }}</td><td class="td">{{ p.reference || '—' }}</td><td class="td"><div v-if="p.status === 'pending'" class="flex gap-2"><button class="btn btn-primary !min-h-[36px] px-3 text-xs" @click="updateSettlement(p.id, 'paid')">Confirmer payé</button><button class="btn btn-ghost !min-h-[36px] px-3 text-xs" @click="updateSettlement(p.id, 'cancelled')">Annuler</button></div><span v-else class="text-muted">—</span></td></tr><tr v-if="!fin?.settlements.length"><td colspan="6" class="td text-center text-muted">Aucun reversement.</td></tr></tbody></table></div>
  <div class="card overflow-x-auto"><h2 class="p-5 text-lg font-bold">Demandes de remboursement</h2><table class="w-full min-w-[560px]"><thead><tr><th class="th">Date</th><th class="th">Commande</th><th class="th">Montant</th><th class="th">Motif</th><th class="th">Statut</th></tr></thead><tbody class="divide-y divide-line"><tr v-for="r in fin?.refunds" :key="r.id"><td class="td">{{ fdate(r.createdAt, { dateStyle: 'short' }) }}</td><td class="td font-mono text-xs">{{ r.orderId.slice(0, 8) }}</td><td class="td">{{ money(r.amount) }}</td><td class="td text-muted">{{ r.reason }}</td><td class="td capitalize">{{ r.status }}</td></tr><tr v-if="!fin?.refunds.length"><td colspan="5" class="td text-center text-muted">Aucune demande.</td></tr></tbody></table></div></div></template>
